def inr_format(n):
    s = str(n)
    result = []
    for i in range(len(s)-1, -1, -2):
        result.append(s[i-2:i] if i >= 2 else s[i])
    return ','.join(reversed(result))

def inr_format(n):
    if n == 0:
        return '0'
    s = str(n)
    reversed_s = s[::-1]
    grouped = []
    for i in range(0, len(reversed_s), 3):
        grouped.append(reversed_s[i:i+3])
    formatted = ','.join(grouped[::-1])
    return formatted

